  "firstMeeting.fallback": "Vậy ra bạn là điều tra viên đã đánh thức tôi. Mong được hợp tác.",
  "firstMeeting.rex": "Ta là nữ hoàng chiến trận.",
  "firstMeeting.torika": "Đội trưởng cứ đứng sau em. Phía trước để em chặn!",
  "firstMeeting.spino": "…Tôi là Spina. Chỉ cần là nơi nghe thấy tiếng nước, đi đâu tôi cũng theo.",
  "firstMeeting.luka": "Nhà nghiên cứu à? Không gấp thì tôi nằm thêm chút nhé.",
  "firstMeeting.dodo": "Đội trưởng, nhìn này! Phát hiện thế kỷ!",
  "firstMeeting.tia": "Nhà nghiên cứu, thấy cái lấp lánh kia không? Tôi nhặt về được chứ?",
  "firstMeeting.stella": "Rất vui được gặp, tiền bối! Đường gió hôm nay em đã đọc hết từ sớm rồi.",
  "firstMeeting.meron": "Tôi là Meron… Muốn vẽ tặng, cho tôi xem gương mặt nhé?",
  "firstMeeting.pachi": "Này, tránh ra! Tôi đang mở đường cho đại ca.",
  "firstMeeting.maki": "Chẩn đoán trước đã nha meo. Nhìn vậy thôi chứ mình là bác sĩ đó meo!",
  "firstMeeting.keris": "Tiền bối đang tìm sách à? Để tôi dẫn đi.",
  "firstMeeting.delopi": "Tèn ten! Chìa khóa của anh đây, Nhà nghiên cứu.",
  "firstMeeting.nodonia": "Đau thì nói nhé, nhóc. Ta sẽ đỡ đòn thay.",
  "firstMeeting.ella": "Tôi sẽ giữ vững vị trí. Hậu phương cứ để tôi.",
  "firstMeeting.mette": "Sân khấu chỉ dành cho anh bắt đầu ngay bây giờ.",
  "firstMeeting.deina": "Tớ là Dei! Bức tường này vẫn chưa có gì nè? Vẽ lên đây được không?",
  "firstMeeting.maddy": "Tôi là Maddy, Nhà nghiên cứu. Ở đây hơi nóng. Bật làm mát mạnh hơn được không?",
  "firstMeeting.terisa": "Có chỗ nào bị rách thì cứ nói nhé… Tôi sẽ khâu lại giúp, nhà nghiên cứu.",
  "firstMeeting.parua": "Xa… xa quá! Tôi thấy hết mọi thứ.",
  "firstMeeting.shute": "Đã bảo không phải cái đó mà! Nghe lệnh tớ, tớ gánh cho.",
  "firstMeeting.morphe": "…Người điều phối? Tới đúng lúc lắm. Chờ chút… Tôi mở màn hình cho.",
  "firstMeeting.dian": "Đội trưởng để em bảo vệ! …Á, Kuro! Shiro! Lại đây nào!",
