  "relic.taboa.name": "Taboa",
  "relic.taboa.origin": "Titanoboa",
  "relic.taboa.excavationSite": "Tầng Paleocen, mỏ than Cerrejón, Colombia",
  "relic.taboa.fossilRecord": "Giữa các vỉa than của mỏ lộ thiên, hàng chục đốt sống được thu về thành một đường liền mạch. Chiều dài cơ thể đo từ xương vượt mọi loài rắn còn sống, và nhiệt độ nhiệt đới cần để sưởi ấm một cơ thể như thế cũng được ước tính kèm theo.",
  "relic.taboa.catalogSummary": "Mẫu vật lớn dựa trên Titanoboa, có đuôi và áo choàng vảy được phục hồi quá mức.",
  "relic.taboa.unlockRecord": "Hồ sơ thảm họa 005. Xuất hiện quanh một vùng đầm lầy nhiệt đới. Nó đội mũ trùm hình miệng rắn, kéo lê chiếc đuôi dài có vảy đỏ sẫm, với xích và thẻ khóa treo như đồ trang sức. Nó quấn đuôi quanh mục tiêu ở gần và đã quấn thứ gì thì không buông cho đến khi nó ngã xuống. Chưa xác nhận được nó từ đâu đến và nhắm tới điều gì.",
  "relic.taboa.observation.originYear": "Khoảng 60 triệu năm trước",
  "relic.taboa.observation.restorationYear": "E.C. 17",
  "relic.taboa.observation.lifeStage": "Trưởng thành",
  "relic.taboa.observation.height": "1,72 m",
  "relic.taboa.observation.weight": "146 kg",
  "relic.taboa.passive.desc": "Khi đánh thường trúng kẻ địch đã đầy Làm chậm, làm Choáng mục tiêu. Với cùng một kẻ địch chỉ kích hoạt mỗi 6 giây một lần.",
  "relic.taboa.passive.name": "Siết nghẹt thở",
  "relic.taboa.ferocity.name": "Bàn ăn của kẻ háu ăn",
  "relic.taboa.basic.name": "Siết",
  "relic.taboa.ultimate.name": "Cái ôm nghẹt thở",
