  "relic.arsa.projectName": "RELENTLESS HUNT",
  "firstMeeting.arsa": "…Arsa. Săn xong rồi hẵng nói chuyện. Vẫn chưa xong đâu.",
  "keyword.gulp.term": "Ực",
  "keyword.gulp.description": "Trạng thái Belz giấu đồng minh trong miệng. Họ [[stealth|Tàng hình]], thoát khỏi tầm nhắm của kẻ địch, và hồi 6% HP tối đa mỗi giây. Khi ẩn vẫn có thể di chuyển và chiến đấu, tấn công cũng không làm mất Tàng hình.",
